import fs from 'fs';
import http from 'http';
import path from 'path';
import type { AddressInfo } from 'net';
import { watch, FSWatcher } from 'chokidar';
import { WebSocket, WebSocketServer } from 'ws';
import { buildSite } from './site';
import { DEFAULT_TEMPLATES_DIR } from './template';

export const DEFAULT_PORT = 3000;
export const LIVERELOAD_PATH = '/__livereload';
export const RELOAD_MESSAGE = 'reload';

export const REBUILD_DELAY_MS = 100;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
  '.webmanifest': 'application/manifest+json; charset=utf-8',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.map': 'application/json; charset=utf-8',
};

export interface ServeOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  port?: number;
}

export interface ServeHandle {
  server: http.Server;
  wss: WebSocketServer;
  watcher: FSWatcher;
  port: number;
  close: () => Promise<void>;
}

export function clientScript(): string {
  return [
    '<script id="__livereload">',
    '(function () {',
    "  var proto = location.protocol === 'https:' ? 'wss://' : 'ws://';",
    `  var ws = new WebSocket(proto + location.host + '${LIVERELOAD_PATH}');`,
    `  ws.onmessage = function (event) {`,
    `    if (event.data === '${RELOAD_MESSAGE}') { location.reload(); }`,
    '  };',
    '})();',
    '</script>',
  ].join('\n');
}

export function hasLiveReload(html: string): boolean {
  return html.includes('id="__livereload"');
}

export function injectLiveReload(html: string): string {
  if (hasLiveReload(html)) return html;
  const script = clientScript();
  const bodyEnd = html.lastIndexOf('</body>');
  if (bodyEnd !== -1) {
    return html.slice(0, bodyEnd) + script + html.slice(bodyEnd);
  }
  const htmlEnd = html.lastIndexOf('</html>');
  if (htmlEnd !== -1) {
    return html.slice(0, htmlEnd) + script + html.slice(htmlEnd);
  }
  return html + script;
}

function contentType(filePath: string): string {
  return MIME_TYPES[path.extname(filePath).toLowerCase()] || 'application/octet-stream';
}

function isHtmlFile(filePath: string): boolean {
  return /\.html?$/i.test(filePath);
}

export function createRequestHandler(
  outputDir: string
): (req: http.IncomingMessage, res: http.ServerResponse) => void {
  return (req, res) => {
    let pathname: string;
    try {
      pathname = decodeURIComponent(new URL(req.url || '/', 'http://localhost').pathname);
    } catch {
      res.writeHead(400, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Bad request');
      return;
    }

    if (pathname === '/') pathname = '/index.html';

    const resolvedRoot = path.resolve(outputDir);
    const filePath = path.join(resolvedRoot, pathname);
    if (!filePath.startsWith(resolvedRoot + path.sep)) {
      res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Forbidden');
      return;
    }

    fs.readFile(filePath, (err, data) => {
      if (err) {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Not found');
        return;
      }
      let body: string | Buffer = data;
      if (isHtmlFile(filePath) && !hasLiveReload(data.toString('utf8'))) {
        body = injectLiveReload(data.toString('utf8'));
      }
      res.writeHead(200, { 'Content-Type': contentType(filePath) });
      res.end(body);
    });
  };
}

export function broadcastReload(wss: WebSocketServer): void {
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send(RELOAD_MESSAGE);
    }
  }
}

export function serve(options: ServeOptions): ServeHandle {
  const contentDir = options.contentDir;
  const outputDir = options.outputDir;
  const templatesDir = options.templatesDir || DEFAULT_TEMPLATES_DIR;
  const port = options.port ?? DEFAULT_PORT;

  if (!fs.existsSync(contentDir)) {
    throw new Error(`content directory not found: ${contentDir}`);
  }

  buildSite(contentDir, outputDir, templatesDir);

  const server = http.createServer(createRequestHandler(outputDir));
  const wss = new WebSocketServer({ server, path: LIVERELOAD_PATH });

  const watchPaths: string[] = [contentDir];
  if (fs.existsSync(templatesDir)) watchPaths.push(templatesDir);

  const watcher = watch(watchPaths, { ignoreInitial: true });

  let timer: NodeJS.Timeout | null = null;
  watcher.on('all', () => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      try {
        buildSite(contentDir, outputDir, templatesDir);
        broadcastReload(wss);
      } catch (err) {
        console.error(
          '[ssg serve] rebuild failed:',
          err instanceof Error ? err.message : err
        );
      }
    }, REBUILD_DELAY_MS);
  });

  const handle: ServeHandle = {
    server,
    wss,
    watcher,
    port,
    close: (): Promise<void> =>
      new Promise((resolve) => {
        if (timer) {
          clearTimeout(timer);
          timer = null;
        }
        watcher.close().then(() => {
          wss.close(() => {
            server.close(() => resolve());
          });
        });
      }),
  };

  server.on('listening', () => {
    const addr = server.address() as AddressInfo;
    if (addr) {
      handle.port = addr.port;
      console.log(`[ssg serve] http://localhost:${addr.port}`);
    }
  });

  server.listen(port);
  return handle;
}

import {
  buildSite,
  DEFAULT_CONTENT_DIR,
  DEFAULT_OUTPUT_DIR,
} from './site';
import { DEFAULT_TEMPLATES_DIR } from './template';
import { serve, DEFAULT_PORT } from './serve';

export interface CliOptions {
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  port?: number;
}

export interface ParsedArgs {
  command: string;
  options: CliOptions;
}

export function printHelp(): void {
  console.log(
    [
      'Usage: ssg <command> [options]',
      '',
      'Commands:',
      '  build    generate a static site from Markdown files',
      '  serve    start a development server with live reload',
      '',
      'Options:',
      '  --content <dir>    directory containing Markdown files (default: ./content)',
      '  --output <dir>     directory to write the generated site (default: ./dist)',
      '  --templates <dir>  directory containing templates (default: ./templates)',
      '  --port <number>    port for the serve command (default: 3000)',
      '  -h, --help         show this help message',
    ].join('\n')
  );
}

export function parseArgs(argv: string[]): ParsedArgs {
  const args = [...argv];
  let command = 'build';
  if (args.length > 0 && !args[0].startsWith('-')) {
    command = args.shift() as string;
  }

  const options: CliOptions = {
    contentDir: DEFAULT_CONTENT_DIR,
    outputDir: DEFAULT_OUTPUT_DIR,
    templatesDir: DEFAULT_TEMPLATES_DIR,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--content' || arg === '-c') {
      const value = args[++i];
      if (value === undefined) {
        throw new Error(`missing value for ${arg}`);
      }
      options.contentDir = value;
    } else if (arg === '--output' || arg === '-o') {
      const value = args[++i];
      if (value === undefined) {
        throw new Error(`missing value for ${arg}`);
      }
      options.outputDir = value;
    } else if (arg === '--templates' || arg === '-t') {
      const value = args[++i];
      if (value === undefined) {
        throw new Error(`missing value for ${arg}`);
      }
      options.templatesDir = value;
    } else if (arg === '--port' || arg === '-p') {
      const value = args[++i];
      if (value === undefined) {
        throw new Error(`missing value for ${arg}`);
      }
      const port = Number(value);
      if (!Number.isInteger(port) || port < 0 || port > 65535) {
        throw new Error(`invalid port: ${value}`);
      }
      options.port = port;
    } else if (arg === '--help' || arg === '-h') {
      printHelp();
      process.exit(0);
    } else {
      throw new Error(`unknown argument: ${arg}`);
    }
  }

  return { command, options };
}

function serveCommand(options: CliOptions): void {
  try {
    const handle = serve({
      contentDir: options.contentDir,
      outputDir: options.outputDir,
      templatesDir: options.templatesDir,
      port: options.port ?? DEFAULT_PORT,
    });
    const port = handle.port;
    console.log(`Serving ${options.outputDir} at http://localhost:${port}`);
    console.log('Watching for changes...');
    let closing = false;
    const shutdown = (): void => {
      if (closing) return;
      closing = true;
      handle.close().then(() => process.exit(0));
    };
    process.on('SIGINT', shutdown);
    process.on('SIGTERM', shutdown);
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  }
}

export function run(argv: string[]): void {
  let parsed: ParsedArgs;
  try {
    parsed = parseArgs(argv);
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  }

  if (parsed.command === 'serve') {
    serveCommand(parsed.options);
    return;
  }

  if (parsed.command !== 'build') {
    console.error(`unknown command: ${parsed.command}`);
    process.exit(1);
  }

  try {
    const result = buildSite(
      parsed.options.contentDir,
      parsed.options.outputDir,
      parsed.options.templatesDir
    );
    const pagesWord = result.pages === 1 ? 'page' : 'pages';
    console.log(`Built ${result.pages} ${pagesWord} into ${result.outputDir}`);
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  }
}

import fs from 'fs';
import http from 'http';
import os from 'os';
import path from 'path';
import { AddressInfo } from 'net';
import WebSocket from 'ws';
import {
  serve,
  ServeHandle,
  LIVERELOAD_PATH,
  DEFAULT_PORT,
  injectLiveReload,
  hasLiveReload,
  REBUILD_DELAY_MS,
} from '../src/serve';
import { parseArgs, printHelp } from '../src/cli';

interface TempDir {
  dir: string;
  cleanup: () => void;
}

function makeTempDir(): TempDir {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-serve-'));
  return { dir, cleanup: () => fs.rmSync(dir, { recursive: true, force: true }) };
}

function writeMarkdown(dir: string, relPath: string, content: string): void {
  const full = path.join(dir, relPath);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content, 'utf8');
}

async function startServer(
  contentDir: string,
  outputDir: string,
  templatesDir?: string
): Promise<{ handle: ServeHandle; port: number }> {
  const handle = serve({ contentDir, outputDir, templatesDir, port: 0 });
  await new Promise<void>((resolve) => handle.server.once('listening', resolve));
  const port = (handle.server.address() as AddressInfo).port;
  return { handle, port };
}

function fetchText(port: number, pathname: string): Promise<string> {
  return new Promise((resolve, reject) => {
    http
      .get({ hostname: 'localhost', port, path: pathname }, (res) => {
        let data = '';
        res.on('data', (chunk) => (data += chunk));
        res.on('end', () => resolve(data));
      })
      .on('error', reject);
  });
}

function fetchStatus(port: number, pathname: string): Promise<number> {
  return new Promise((resolve, reject) => {
    http
      .get({ hostname: 'localhost', port, path: pathname }, (res) => {
        res.resume();
        res.on('end', () => resolve(res.statusCode || 0));
      })
      .on('error', reject);
  });
}

async function waitFor(
  fn: () => boolean,
  timeoutMs: number = 5000
): Promise<void> {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (fn()) return;
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
  throw new Error('waitFor timed out');
}

function nextWsMessage(ws: WebSocket): Promise<string> {
  return new Promise((resolve, reject) => {
    ws.on('message', (data) => resolve(String(data)));
    ws.on('error', reject);
  });
}

function openLiveReloadSocket(port: number): Promise<WebSocket> {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(`ws://localhost:${port}${LIVERELOAD_PATH}`);
    ws.on('open', () => resolve(ws));
    ws.on('error', reject);
  });
}

describe('parseArgs for serve', () => {
  it('treats serve as a command', () => {
    const { command } = parseArgs(['serve']);
    expect(command).toBe('serve');
  });

  it('parses the --port option', () => {
    const { options } = parseArgs(['serve', '--port', '4321']);
    expect(options.port).toBe(4321);
  });

  it('parses the shorthand -p port option', () => {
    const { options } = parseArgs(['serve', '-p', '8080']);
    expect(options.port).toBe(8080);
  });

  it('leaves port unset when not provided', () => {
    const { options } = parseArgs(['serve']);
    expect(options.port).toBeUndefined();
  });

  it('throws when a port value is missing', () => {
    expect(() => parseArgs(['serve', '--port'])).toThrow(/missing value/);
  });

  it('throws on an invalid port value', () => {
    expect(() => parseArgs(['serve', '--port', 'abc'])).toThrow(/invalid port/);
    expect(() => parseArgs(['serve', '--port', '-1'])).toThrow(/invalid port/);
    expect(() => parseArgs(['serve', '--port', '70000'])).toThrow(/invalid port/);
  });

  it('exports the default port', () => {
    expect(DEFAULT_PORT).toBe(3000);
  });

  it('prints serve in the help text', () => {
    const spy = jest.spyOn(console, 'log').mockImplementation(() => {});
    expect(() => printHelp()).not.toThrow();
    expect(spy).toHaveBeenCalled();
    const output = spy.mock.calls.map((c) => c.join(' ')).join('\n');
    expect(output).toContain('serve');
    expect(output).toContain('--port');
    spy.mockRestore();
  });
});

describe('injectLiveReload', () => {
  it('injects the script before </body>', () => {
    const html = '<html><body><p>Hi</p></body></html>';
    const out = injectLiveReload(html);
    expect(out).toContain('<p>Hi</p>');
    expect(out.indexOf('__livereload')).toBeLessThan(out.indexOf('</body>'));
  });

  it('injects before </html> when there is no </body>', () => {
    const html = '<html><p>Hi</p></html>';
    const out = injectLiveReload(html);
    expect(out.indexOf('__livereload')).toBeLessThan(out.indexOf('</html>'));
  });

  it('does not inject twice', () => {
    const once = injectLiveReload('<html><body></body></html>');
    expect(hasLiveReload(once)).toBe(true);
    const twice = injectLiveReload(once);
    const count = (twice.match(/__livereload/g) || []).length;
    expect(count).toBe(1);
  });

  it('appends the script when there is no body or html tag', () => {
    const html = '<p>Hi</p>';
    expect(injectLiveReload(html)).toContain('__livereload');
  });
});

describe('serve dev server', () => {
  it('builds and serves the site with the live-reload script injected', async () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    const outDir = path.join(dir, 'dist');
    writeMarkdown(contentDir, 'one.md', '---\ntitle: First\n---\nHello **world**.');
    const { handle, port } = await startServer(contentDir, outDir);
    try {
      const index = await fetchText(port, '/');
      expect(index).toContain('Hello');
      expect(index).toContain('First');
      expect(index).toContain('id="__livereload"');
      expect(index).toContain(LIVERELOAD_PATH);

      const page = await fetchText(port, '/first.html');
      expect(page).toContain('<strong>world</strong>');
      expect(page).toContain('id="__livereload"');
    } finally {
      await handle.close();
      cleanup();
    }
  });

  it('serves an injected page only once after rebuild', async () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    const outDir = path.join(dir, 'dist');
    writeMarkdown(contentDir, 'one.md', '---\ntitle: First\n---\nHello.');
    const { handle, port } = await startServer(contentDir, outDir);
    try {
      const first = await fetchText(port, '/');
      const second = await fetchText(port, '/');
      expect((first.match(/id="__livereload"/g) || []).length).toBe(1);
      expect(second).toBe(first);
    } finally {
      await handle.close();
      cleanup();
    }
  });

  it('returns a 404 for missing files', async () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    const outDir = path.join(dir, 'dist');
    writeMarkdown(contentDir, 'one.md', '# Hello');
    const { handle, port } = await startServer(contentDir, outDir);
    try {
      expect(await fetchStatus(port, '/nope.html')).toBe(404);
    } finally {
      await handle.close();
      cleanup();
    }
  });

  it('rebuilds and broadcasts reload when content changes', async () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    const outDir = path.join(dir, 'dist');
    writeMarkdown(contentDir, 'one.md', '---\ntitle: One\n---\nFirst body.');
    const { handle, port } = await startServer(contentDir, outDir);
    const ws = await openLiveReloadSocket(port);
    try {
      const reloadPromise = nextWsMessage(ws);
      writeMarkdown(contentDir, 'two.md', '---\ntitle: Two\n---\nSecond body.');
      await reloadPromise;

      await waitFor(async () => {
        const index = await fetchText(port, '/');
        return index.includes('Second body.');
      });

      const page = await fetchText(port, '/two.html');
      expect(page).toContain('Second body.');
    } finally {
      ws.close();
      await handle.close();
      cleanup();
    }
  });

  it('rebuilds and broadcasts reload when a template changes', async () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    const outDir = path.join(dir, 'dist');
    const templatesDir = path.join(dir, 'templates');
    writeMarkdown(contentDir, 'one.md', '---\ntitle: One\n---\nBody.');
    writeMarkdown(templatesDir, 'page.hbs', 'PAGE OLD: {{title}}');
    const { handle, port } = await startServer(contentDir, outDir, templatesDir);
    const ws = await openLiveReloadSocket(port);
    try {
      const reloadPromise = nextWsMessage(ws);
      writeMarkdown(templatesDir, 'page.hbs', 'PAGE NEW: {{title}}');
      await reloadPromise;

      await waitFor(async () => {
        const index = await fetchText(port, '/');
        return index.includes('PAGE NEW: One');
      });
    } finally {
      ws.close();
      await handle.close();
      cleanup();
    }
  });

  it('serves after a debounced burst of changes', async () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    const outDir = path.join(dir, 'dist');
    writeMarkdown(contentDir, 'one.md', '---\ntitle: One\n---\nA.');
    const { handle, port } = await startServer(contentDir, outDir);
    try {
      for (let i = 0; i < 5; i++) {
        writeMarkdown(contentDir, 'one.md', `---\ntitle: One\n---\nUpdate ${i}.`);
        await new Promise((resolve) => setTimeout(resolve, REBUILD_DELAY_MS / 2));
      }
      await waitFor(async () => {
        const page = await fetchText(port, '/one.html');
        return page.includes('Update 4.');
      });
    } finally {
      await handle.close();
      cleanup();
    }
  });
});

