export NVM_DIR="$HOME/.nvm" && . "$NVM_DIR/nvm.sh" && npx tsc && node -e "
const { serve } = require('./dist/serve');
const fs = require('fs');
const os = require('os');
const path = require('path');
const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-smoke-'));
fs.mkdirSync(path.join(dir, 'content'), { recursive: true });
fs.writeFileSync(path.join(dir, 'content', 'hello.md'), '---\ntitle: Hello\n---\nHi there.');
const handle = serve({ contentDir: path.join(dir,'content'), outputDir: path.join(dir,'dist'), port: 0 });
handle.server.once('listening', async () => {
  const port = handle.server.address().port;
  const http = require('http');
  http.get({ hostname: 'localhost', port, path: '/' }, (res) => {
    let d=''; res.on('data', c => d+=c); res.on('end', async () => {
      console.log('status', res.statusCode);
      console.log('has livereload:', d.includes('id=\"__livereload\"'));
      console.log('has Hello:', d.includes('Hello'));
      await handle.close();
      fs.rmSync(dir, { recursive: true, force: true });
      console.log('closed cleanly');
    });
  });
});
"

